float harmonicArc( in vec2 z, in vec2 p0, in vec2 q0, in vec2 p1, in vec2 q1 ) { 

    vec2 f = div( mul(z-p0,z-q0), mul(z-p1,z-q1) );

    return im( clog( f ) );
}

float safeStep( in vec2 z, in vec2 p0, in vec2 q0, in vec2 p1, in vec2 q1 ) { 
    float R = min(min(length(z-p0), length(z-q0)), min(length(z-p1), length(z-q1)));

    // (R-r)/(R+r) f0 <= f1 <= (R+r)/(R-r) f0
    // f1 >= cl <-  (R-r)/(R+r) f0 >= cl
    //          <-> r (cl + f0) <= R(f0 - cl)
    //          <-> r <= R (f0 - cl) / (f0 + cl)
    // f1 <= cu <-  (R+r)/(R-r) f0 <= cu
    //          <-> r (cu + f0) <= R(cu - f0)
    //          <-> r <= R (cu - f0) / (cu + f0)

    float shift = 2.5;

    vec2 f = div( mul(z-p0,z-q0), mul(z-p1,z-q1) ); 
    float f0 = mod(im( clog( f ) ) - PI + 2. * PI, 2. * PI) + shift;

    float rl = R * (f0 - shift) / (f0 + shift);
    float ru = R * (2. * PI + shift - f0) / (2. * PI + shift + f0);

    return min(rl, ru);
}

vec3 disk(vec2 z, vec2 c, float r, vec3 C0, vec3 C1) {
   float x = sqrt( dot(c-z,c-z) );
   float s = 1.;
   if( x < r ) s = 0.;
   return min(C1, C0 + s*(C1-C0));
}

