{
    // normalized pixel coordinates
    vec2 z = (fragCoord-iResolution.xy/2.)/iResolution.x;
    vec2 m = (iMouse.xy-iResolution.xy/2.)/iResolution.x;

    // animation
    float time = iTime;
    float tb = .1*3.14+.4*3.14*(0.5+0.5*cos(time*0.31+2.0));
    float ra = 0.85;
    float rb = .05;//0.15*(0.5+0.5*cos(time*0.41+3.0));
    // vec2  sc = vec2(sin(tb),cos(tb));

    vec2 noise0 = vec2(cos(.73*time),sin(.2*time));
    vec2 noise1 = vec2(cos(-.3*time),sin(.4*time));

    // singularities
    float r = 0.125;
    float dy = .05;
    vec2 q0 = vec2(0.,r + dy) - .1 * noise1;
    vec2 p0 = vec2(0.,-r + dy) + .1 * noise0;
    vec2 q1 = vec2(-1. * r,r/2. + dy) - .1 * noise0;
    vec2 p1 = vec2(-1.8 * r, r / 3. + dy) - .1 * noise1;//vec2(r,-r/2.); 

    // distance
    float thickness = .1;
    float d = harmonicArc( z, q0, p0, q1, p1 );//sdArc(p,sc,ra,rb)-thickness;

    // stripes
    const float w = .05;
    const float s = 10.;
    float u = floor(mod(s*d,2.));
    float v = abs(s*d-round(s*d)) < w ? 0. : 1.;
    float tau = v*(.5+.5*u);
    vec3 color2 = vec3(255.,243.,191.)/255.;
    vec3 color1 = vec3(255.,168.,119.)/255.;
    vec3 col = (1.-tau)*color1 + tau*color2;

    // ray
    float rayWidth = 0.0025;
    float dashing = 36.;
    float dotSize = .01;
    vec2 r0 = (vec2(-.7,-.8) + .1*vec2(cos(1.43*time),sin(2.0*time))) / 4.;
    vec2 rd = vec2(.5,1.) + .2*vec2(cos(.72*time),sin(1.5*time));
    rd = normalize(rd);
    vec2 rn = vec2(-rd.y,rd.x);
    float rayT = dot(rd,z-r0);
    bool onDash = fract(dashing*rayT)<.5;
    bool onDot = length(z-r0) < dotSize;
    bool onRay = (abs(dot(rn,z-r0)) < rayWidth);
    col *= (onRay && (rayT > 0.) && onDash) || onDot ? 0.4 : 1.;

    // spheres
    int nSteps = 64;
    float t = 0.;
    float eps = .0001;
    bool hit = false;
    float hit_r = 10.;
    float t_overstep = 0.;
    vec3 sphere_col = 1.2 * vec3(19.,71.,73.)/255.;
    for( int i = 0; i < nSteps && !hit; i++ )
    { 
       vec2 rt = r0 + t*rd + t_overstep * rd;
       // float dt = sdArc(rt,sc,ra,rb)-thickness;;
       float dt = safeStep(rt, q0, p0, q1, p1 );

       // overstep was valid if dt >= t_overstep
       bool valid_overstep = dt >= t_overstep;
       float stepSize = (valid_overstep) ? t_overstep + dt : 0.;
       t_overstep = (valid_overstep) ? .2 * dt : 0.;

       if (valid_overstep) {
           float r = length(z-rt);
           if( r < dt ) {
               float s = ( r < dt-.005 ? .7 : .1 );
               col = s * col + (1. - s) * sphere_col;
           }
           if( t > 0. && r < .65*dotSize ) col = sphere_col;
           if( t > 0. && dt < eps && r < dotSize ) { hit = true; hit_r = r; break; }

           t += stepSize;
       }
    }

    // singularity dots
    vec3 accentColor =  vec3( 0. );
    vec3 white = (1.-.3)*accentColor + .3*col;//vec3( 1., 1., 1. );
    vec3 black = (1.-.3)*accentColor + .3*col;//vec3( 0., 0., 0. );
    // col = disk(z, p0, dotSize, white, col );
    // col = disk(z, q0, dotSize, white, col );
    // col = disk(z, p1, dotSize, black, col );
    // col = disk(z, q1, dotSize, black, col );

    // solid shape
    float bdy = smoothstep( 1.5 * w, 2. * w, abs( d - PI ) ) ;//abs( d - PI ) < 2. * w ? 0. : 1.; // d < 0. ? .3 : 1.;
    col = min(col, (1.-bdy)*accentColor + bdy*col);


    if( iMouse.z>0.001 )
    {
    // d = sdArc(m,sc, 0.7, rb);
    d = safeStep(m, q0, p0, q1, p1 );
    col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, abs(length(z-m)-abs(d))-0.0025));
    col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, length(z-m)-0.005));
    }

    if ( hit ) col = hit_r < dotSize - .005 ? vec3(1.) : vec3( 0. );

	fragColor = vec4(col, 1.0);
}

//=== Complex arithmetic from https://www.shadertoy.com/view/NlG3DD

// Constants
float PI = 3.14159265358979323846;
vec2 ii = vec2( 0., 1. ); // imaginary unit


// Operations on complex numbers (represented as vec2)

// real part
float re(vec2 z) {
   return z.x;
}

// imaginary part
float im(vec2 z) {
   return z.y;
}

// complex logarithm
vec2 clog(vec2 x) {
    return vec2(log(x.x), atan(x.y, x.x));
}

// complex exponential
vec2 cexp(vec2 z) {
   return exp(z.x)*vec2(cos(z.y),sin(z.y)); 
}

// complex power
vec2 cpow(vec2 z, float n) {
   float r = length(z);
   float theta = atan(z.y,z.x);
   return pow(r,n)*vec2(cos(n*theta),sin(n*theta));
}

// complex multiplication
vec2 mul(vec2 a, vec2 b) {
    return vec2(a.x * b.x - a.y * b.y,
                a.x * b.y + a.y * b.x);
}

// complex conjugation
vec2 conj(vec2 a) {
    return vec2(a.x, -a.y);
}

// complex inverse
vec2 inv(vec2 a) {
   return conj(a)/dot(a,a);
}

// complex division
vec2 div(vec2 a, vec2 b) {
    return mul(a,inv(b));
}

// Wirtinger derivative
vec2 dFdz(vec2 p) {
   return dFdx(p) + mul(ii,dFdy(p));
}

// harmonic segment
float segment(vec2 z, vec2 p, vec2 q) {
    return clog(div((z - p), (z - q))).y;
}

// map value in range [-π,π) to [0,1)
float unitRange(float x) {
    return .5 + .5*x/PI;
}

// map scalar value to pseudocolor
vec3 colorMap(float x) {

    x = .5 + .5*x/PI;
    vec3 colA = vec3(.5, 1, 0);
    vec3 colB = vec3(0, .5, 1);
    return colA * x + colB * (1.0f - x);
}
